function updateKetersediaanDependents() {
    const backupCheckbox = document.getElementById('rekam-backup-checkbox');
    const wrapper = document.getElementById('alasan-ketidaktersediaan-wrapper');

    if (statusTidakTersedia && statusTidakTersedia.checked) {
        // Data Tidak Tersedia selected
        if (wrapper) wrapper.style.display = '';

        // Enable Alasan Ketidaktersediaan
        if (alasanKetidaktersedianInput) {
            alasanKetidaktersedianInput.disabled = false;
            alasanKetidaktersedianInput.required = true;
            alasanKetidaktersedianInput.style.opacity = '1';
        }

        // Find and select "Data Tidak Tersedia" option in Bentuk Data, then disable
        if (bentukDataSelect) {
            const tidakTersediaOption = Array.from(bentukDataSelect.options).find(
                opt => opt.text.toLowerCase().includes('tidak tersedia') || 
                       opt.textContent.toLowerCase().includes('tidak tersedia')
            );
            if (tidakTersediaOption) {
                bentukDataSelect.value = tidakTersediaOption.value;
            }
            bentukDataSelect.disabled = true;
            bentukDataSelect.style.opacity = '0.6';
        }

        // Find and select "Data Tidak Tersedia" option in Cara Penyampaian, then disable
        if (caraPenyampaianSelect) {
            const tidakTersediaOption = Array.from(caraPenyampaianSelect.options).find(
                opt => opt.text.toLowerCase().includes('tidak tersedia') || 
                       opt.textContent.toLowerCase().includes('tidak tersedia')
            );
            if (tidakTersediaOption) {
                caraPenyampaianSelect.value = tidakTersediaOption.value;
            }
            caraPenyampaianSelect.disabled = true;
            caraPenyampaianSelect.style.opacity = '0.6';
        }

        // Set Baris Diterima to 0 and disable
        if (barisDiterimaInput) {
            barisDiterimaInput.value = 0;
            barisDiterimaInput.disabled = true;
            barisDiterimaInput.style.opacity = '0.6';
        }

        // Disable and uncheck Rekam Backup Data toggle
        if (backupCheckbox) {
            backupCheckbox.checked = false;
            backupCheckbox.disabled = true;
            // Trigger backup section hide
            const backupSection = document.getElementById('backup-data-section');
            if (backupSection) {
                backupSection.style.display = 'none';
            }
        }
    } else {
        // Data Tersedia selected
        if (wrapper) wrapper.style.display = 'none';

        // Disable Alasan Ketidaktersediaan
        if (alasanKetidaktersedianInput) {
            alasanKetidaktersedianInput.disabled = true;
            alasanKetidaktersedianInput.required = false;
            alasanKetidaktersedianInput.value = '';
        }

