// Special Request Card highlight listener
const specialRequestInput = document.getElementById('id_special_request');
const specialRequestCard = document.getElementById('special-request-card');
function updateSpecialRequestCard() {
    if (specialRequestInput && specialRequestCard) {
        if (specialRequestInput.checked) {
            specialRequestCard.style.backgroundColor = 'rgba(245, 158, 11, 0.08)';
            specialRequestCard.style.borderColor = '#f59e0b';
        } else {
            specialRequestCard.style.backgroundColor = '#ffffff';
            specialRequestCard.style.borderColor = '#e2e8f0';
        }
    }
}
if (specialRequestInput) {
    specialRequestInput.addEventListener('change', updateSpecialRequestCard);
    updateSpecialRequestCard();
}

// Helper: validate mandatory form fields
function validateMandatoryForm() {
    let isValid = true;
    let firstInvalid = null;

    const mandatoryConfigs = [
        { id: 'id_ilap', label: 'ILAP' },
        { id: 'id_periode_data', label: 'Jenis Data ILAP' },
        { id: 'id_periode', label: 'Periode' },
        { id: 'id_tahun', label: 'Tahun' },
        { id: 'id_tgl_terima_vertikal', label: 'Tanggal Terima Vertikal' },
        { id: 'id_tgl_terima_dip', label: 'Tanggal Terima DIP' },
        { id: 'id_id_bentuk_data', label: 'Bentuk Data' },
        { id: 'id_id_cara_penyampaian', label: 'Cara Penyampaian' },
        { id: 'id_satuan_data', label: 'Satuan Data' },
    ];

    if (statusTidakTersedia && statusTidakTersedia.checked) {
        mandatoryConfigs.push({ id: 'id_alasan_ketidaktersediaan', label: 'Alasan Ketidaktersediaan' });
    } else {
        mandatoryConfigs.push({ id: 'id_baris_diterima', label: 'Jumlah Baris Data Diterima' });
    }

    mandatoryConfigs.forEach(cfg => {
        const el = document.getElementById(cfg.id);
        if (el) {
            el.classList.remove('is-invalid');
            const val = el.value ? el.value.trim() : '';
            if (!val || val === '' || val === null) {
                isValid = false;
                el.classList.add('is-invalid');
                if (!firstInvalid) firstInvalid = el;
            }
        }
    });

    if (!isValid && firstInvalid) {
        firstInvalid.focus();
        if (firstInvalid.scrollIntoView) {
            firstInvalid.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
        showValidationModal(
            'Formulir Belum Lengkap!',
            [],
            'Mohon lengkapi seluruh kolom wajib bertanda (*) yang ditandai berwarna merah sebelum melanjutkan.'
        );
    }
    return isValid;
}

// Handle confirmation button click
if (btnConfirm) {
    btnConfirm.addEventListener('click', function(e) {
        e.preventDefault();

        // Custom mandatory validation first
        if (!validateMandatoryForm()) {
            return;
        }

        // Validate form standard HTML5 rules
        if (!form.checkValidity()) {
            form.reportValidity();
            return;
        }

