function createFixedBadge(value, bg, color, border) {
    const num = (value === null || value === undefined || value === '' || isNaN(value)) ? 0 : Number(value);
    const formatted = num.toLocaleString('id-ID');
    return `<span class="badge d-inline-flex justify-content-end align-items-center" style="width: 100px; min-width: 100px; background-color: ${bg}; color: ${color}; font-size: 12px; font-weight: 600; padding: 5px 10px; border-radius: 6px; border: 1px solid ${border}; font-variant-numeric: tabular-nums; text-align: right;">${formatted}</span>`;
}

