// Apply text truncation to descriptive columns to prevent horizontal overflow
columns = columns.map(col => {
    if (['nama_ilap', 'nama_sub_jenis_data', 'nama_jenis_data', 'nama_tabel_I'].includes(col.data) && !col.render) {
        return {
            ...col,
            render: function(data) {
                if (data === null || data === undefined || data === '') return '-';
                const text = String(data);
                const esc = text.replace(/"/g, '&quot;');
                return `<div class="text-truncate" style="max-width: 250px; cursor: pointer;" data-bs-toggle="tooltip" data-bs-placement="top" data-bs-title="${esc}" title="${esc}">${esc}</div>`;
            }
        };
    }
    return col;
});

$(table).on('xhr.dt', function (e, settings, json, xhr) {
    if (json && json.summary) {
        const totalTiketEl = document.getElementById(`summary-total-tiket-${category}`);
        const totalIlapEl = document.getElementById(`summary-total-ilap-${category}`);
        let totalIlapEl2 = totalIlapEl;
        if (category === 'tiket_pengendalian_mutu_tanpa_pic') {
            totalIlapEl2 = document.getElementById('summary-total-ilap-tiket_pengendalian_mutu_tan_pic');
        }
        const totalJenisDataEl = document.getElementById(`summary-total-jenis-data-${category}`);
        let totalJenisDataEl2 = totalJenisDataEl;
        if (category === 'tiket_pengendalian_mutu_tanpa_pic') {
            totalJenisDataEl2 = document.getElementById('summary-total-jenis-data-tiket_pengendalian_mutu_tan_pic');
        }

        if (totalTiketEl) totalTiketEl.textContent = json.summary.total_tiket || 0;
        if (totalIlapEl2) totalIlapEl2.textContent = json.summary.total_ilap || 0;
        if (totalJenisDataEl2) totalJenisDataEl2.textContent = json.summary.total_jenis_data || 0;

        // Save lists for tooltips/modal
        categorySummaryData[category] = {
            ilap_list: json.summary.ilap_list || [],
            jenis_data_list: json.summary.jenis_data_list || []
        };

        // Dynamically update tooltips for this category if interactive wrappers exist
        updateSummaryTooltip(`summary-ilap-wrapper-${category}`, json.summary.ilap_list || [], 'ILAP');
        updateSummaryTooltip(`summary-jenis-wrapper-${category}`, json.summary.jenis_data_list || [], 'Jenis Data');

        // Update urgency count elements if they exist
        if (json.summary.critical_count !== undefined) {
            const countAllEl = document.getElementById(`count-all-${category}`);
            const countCriticalEl = document.getElementById(`count-critical-${category}`);
            const countWarningEl = document.getElementById(`count-warning-${category}`);
            const countNewEl = document.getElementById(`count-new-${category}`);

            if (countAllEl) countAllEl.textContent = json.summary.total_tiket || 0;
            if (countCriticalEl) countCriticalEl.textContent = json.summary.critical_count || 0;
            if (countWarningEl) countWarningEl.textContent = json.summary.warning_count || 0;
            if (countNewEl) countNewEl.textContent = json.summary.new_count || 0;
        }
    }
});


