$(document).on('mouseenter', '.cell-truncate', function() {
    const el = this;
    if (el.scrollWidth > el.clientWidth) {
        const fullText = el.getAttribute('data-full-text') || el.innerText;
        let tooltip = bootstrap.Tooltip.getInstance(el);
        if (!tooltip) {
            tooltip = new bootstrap.Tooltip(el, {
                title: fullText,
                placement: 'top',
                animation: true,
                trigger: 'manual',
                container: 'body'
            });
        } else {
            tooltip.setContent({ '.tooltip-inner': fullText });
        }
        tooltip.show();
    }
}).on('mouseleave', '.cell-truncate', function() {
    const tooltip = bootstrap.Tooltip.getInstance(this);
    if (tooltip) {
        tooltip.hide();
    }
});

