            render: function(data, type, row) {
                if (data === null || data === undefined || data === '') return '-';
                const sub_jenis = String(data);
                const tabel_i = row.nama_tabel_I || '';
                const esc_sub_jenis = sub_jenis.replace(/"/g, '&quot;');
                const esc_tabel_i = String(tabel_i).replace(/"/g, '&quot;');

                let subHtml = '';
                if (tabel_i) {
                    subHtml = `<small class="text-muted d-block font-monospace" style="font-size: 11px; line-height: 1.25; color: #64748b;">${esc_tabel_i}</small>`;
                }
                return `<div>
                    ${subHtml}
                    <div class="text-truncate cell-truncate fw-medium" style="max-width: 250px;" data-full-text="${esc_sub_jenis}">${esc_sub_jenis}</div>
                </div>`;
            }
        };
    }
    if (['nama_ilap'].includes(col.data) && !col.render) {
        return {
            ...col,
